-- Phase 8A: authoritative live Festival runtime foundation.
-- Additive and opt-in: this migration never creates a runtime for an existing launch.
CREATE TABLE public.festival_runtime_sessions (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), festival_launch_id uuid UNIQUE NOT NULL REFERENCES public.festival_launches(id), launch_snapshot_id uuid NOT NULL REFERENCES public.festival_launch_snapshots(id),
 status text NOT NULL DEFAULT 'created' CHECK(status IN('created','pre_event','site_setup','ready_to_open','gates_open','live','final_performance_complete','public_closed','site_clearance','runtime_complete','paused','emergency_hold','cancelled','failed')),
 status_before_hold text, runtime_seed text NOT NULL, attendance_seed text NOT NULL, operations_seed text NOT NULL, incident_seed text NOT NULL,
 engine_version text NOT NULL DEFAULT 'canonical-gig-v1', formula_version text NOT NULL DEFAULT 'festival-runtime-v1', site_capacity integer NOT NULL CHECK(site_capacity>=0), version integer NOT NULL DEFAULT 1 CHECK(version>0),
 gates_open boolean NOT NULL DEFAULT false, admissions_paused boolean NOT NULL DEFAULT false, setup_complete boolean NOT NULL DEFAULT false, ticket_system_available boolean NOT NULL DEFAULT true,
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE public.festival_runtime_days(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),runtime_session_id uuid NOT NULL REFERENCES public.festival_runtime_sessions(id),festival_date date NOT NULL,day_number integer NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,day_seed text NOT NULL,status text NOT NULL DEFAULT 'scheduled',version integer NOT NULL DEFAULT 1,UNIQUE(runtime_session_id,festival_date));
CREATE TABLE public.festival_runtime_stages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),runtime_session_id uuid NOT NULL REFERENCES public.festival_runtime_sessions(id),source_stage_id uuid NOT NULL,stage_name text NOT NULL,capacity integer NOT NULL CHECK(capacity>=0),stage_seed text NOT NULL,status text NOT NULL DEFAULT 'closed' CHECK(status IN('closed','preparing','ready','open','performance_live','changeover','paused','failed')),safety_ready boolean NOT NULL DEFAULT false,crew_ready boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,UNIQUE(runtime_session_id,source_stage_id));
CREATE TABLE public.festival_runtime_performances(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),runtime_session_id uuid NOT NULL REFERENCES public.festival_runtime_sessions(id),runtime_day_id uuid NOT NULL REFERENCES public.festival_runtime_days(id),runtime_stage_id uuid NOT NULL REFERENCES public.festival_runtime_stages(id),source_timetable_id uuid UNIQUE NOT NULL REFERENCES public.festival_public_timetable(id),artist_booking_id uuid,solo_artist_profile_id uuid,band_id uuid,npc_artist_id uuid,artist_name text NOT NULL,scheduled_start timestamptz NOT NULL,scheduled_end timestamptz NOT NULL,actual_start timestamptz,actual_end timestamptz,status text NOT NULL DEFAULT 'scheduled' CHECK(status IN('scheduled','awaiting_artist','artist_ready','stage_ready','ready','starting','live','completed','delayed','cancelled','abandoned','failed')),performance_seed text NOT NULL,engine_version text NOT NULL,formula_version text NOT NULL,engine_input_snapshot jsonb,engine_result_snapshot jsonb,performance_score numeric,technical_score numeric,setlist_score numeric,artist_score numeric,crowd_response text,estimated_audience integer,delay_impact numeric,delay_minutes integer NOT NULL DEFAULT 0,version integer NOT NULL DEFAULT 1,CHECK(num_nonnulls(solo_artist_profile_id,band_id,npc_artist_id)=1));
CREATE TABLE public.festival_runtime_artist_checkins(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),runtime_performance_id uuid UNIQUE NOT NULL REFERENCES public.festival_runtime_performances(id),status text NOT NULL DEFAULT 'expected' CHECK(status IN('expected','checked_in','late','missing','cancelled','waived')),checked_in_by_profile_id uuid REFERENCES public.profiles(id),expected_at timestamptz,checked_in_at timestamptz,version integer NOT NULL DEFAULT 1);
CREATE TABLE public.festival_runtime_band_member_attendance(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),runtime_performance_id uuid NOT NULL REFERENCES public.festival_runtime_performances(id),profile_id uuid NOT NULL REFERENCES public.profiles(id),status text NOT NULL DEFAULT 'expected' CHECK(status IN('expected','present','late','missing','substituted','excused')),required boolean NOT NULL DEFAULT true,checked_in_at timestamptz,version integer NOT NULL DEFAULT 1,UNIQUE(runtime_performance_id,profile_id));
CREATE TABLE public.festival_runtime_staff_checkins(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),runtime_session_id uuid NOT NULL REFERENCES public.festival_runtime_sessions(id),staff_shift_id uuid UNIQUE NOT NULL REFERENCES public.festival_staff_shifts(id),profile_id uuid REFERENCES public.profiles(id),npc_staff_id uuid,status text NOT NULL DEFAULT 'expected' CHECK(status IN('expected','checked_in','late','checked_out','missing','cancelled')),safety_critical boolean NOT NULL DEFAULT false,expected_start timestamptz NOT NULL,expected_end timestamptz NOT NULL,checked_in_at timestamptz,checked_out_at timestamptz,version integer NOT NULL DEFAULT 1,CHECK(num_nonnulls(profile_id,npc_staff_id)=1));
CREATE TABLE public.festival_runtime_supplier_checkins(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),runtime_session_id uuid NOT NULL REFERENCES public.festival_runtime_sessions(id),supplier_contract_id uuid UNIQUE NOT NULL REFERENCES public.festival_supplier_contracts(id),supplier_company_id uuid,npc_supplier_id uuid,status text NOT NULL DEFAULT 'expected' CHECK(status IN('expected','arrived','late','departed','missing','cancelled')),essential boolean NOT NULL DEFAULT false,delivery_start timestamptz,delivery_end timestamptz,arrived_at timestamptz,departed_at timestamptz,version integer NOT NULL DEFAULT 1,CHECK(num_nonnulls(supplier_company_id,npc_supplier_id)=1));
CREATE TABLE public.festival_runtime_gate_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),runtime_session_id uuid NOT NULL REFERENCES public.festival_runtime_sessions(id),runtime_day_id uuid UNIQUE NOT NULL REFERENCES public.festival_runtime_days(id),status text NOT NULL DEFAULT 'closed' CHECK(status IN('closed','ready','open','paused')),opens_at timestamptz,closes_at timestamptz,blocking_failures jsonb NOT NULL DEFAULT '[]',warnings jsonb NOT NULL DEFAULT '[]',version integer NOT NULL DEFAULT 1);
CREATE TABLE public.festival_runtime_ticket_admissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),runtime_session_id uuid NOT NULL REFERENCES public.festival_runtime_sessions(id),runtime_day_id uuid NOT NULL REFERENCES public.festival_runtime_days(id),issued_ticket_id uuid NOT NULL REFERENCES public.festival_issued_tickets(id),gate_reference text NOT NULL,admitted_by_profile_id uuid REFERENCES public.profiles(id),idempotency_key uuid NOT NULL,admitted_at timestamptz NOT NULL DEFAULT now(),UNIQUE(runtime_day_id,issued_ticket_id),UNIQUE(runtime_session_id,idempotency_key));
CREATE TABLE public.festival_runtime_attendance(runtime_session_id uuid NOT NULL REFERENCES public.festival_runtime_sessions(id),runtime_day_id uuid PRIMARY KEY REFERENCES public.festival_runtime_days(id),admitted_count integer NOT NULL DEFAULT 0 CHECK(admitted_count>=0),exited_count integer NOT NULL DEFAULT 0 CHECK(exited_count>=0),onsite_count integer GENERATED ALWAYS AS(admitted_count-exited_count) STORED,capacity integer NOT NULL CHECK(capacity>=0),version integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),CHECK(admitted_count-exited_count<=capacity));
CREATE TABLE public.festival_runtime_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),runtime_session_id uuid NOT NULL REFERENCES public.festival_runtime_sessions(id),runtime_day_id uuid REFERENCES public.festival_runtime_days(id),runtime_stage_id uuid REFERENCES public.festival_runtime_stages(id),runtime_performance_id uuid REFERENCES public.festival_runtime_performances(id),job_type text NOT NULL CHECK(job_type IN('start_site_setup','evaluate_gate_readiness','open_gates','close_gates','prepare_stage','start_performance','resolve_performance','start_changeover','complete_changeover','close_stage','close_public_site','start_site_clearance','complete_runtime','refresh_runtime_summary')),run_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','claimed','completed','failed','paused')),attempts integer NOT NULL DEFAULT 0,locked_at timestamptz,locked_by text,last_error text,completed_at timestamptz,dedupe_key text NOT NULL,UNIQUE(runtime_session_id,dedupe_key));
CREATE TABLE public.festival_runtime_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),runtime_session_id uuid NOT NULL REFERENCES public.festival_runtime_sessions(id),event_type text NOT NULL,entity_type text,entity_id uuid,public_payload jsonb NOT NULL DEFAULT '{}',private_payload jsonb NOT NULL DEFAULT '{}',dedupe_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(runtime_session_id,dedupe_key));
CREATE TABLE public.festival_runtime_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),runtime_session_id uuid NOT NULL REFERENCES public.festival_runtime_sessions(id),snapshot_type text NOT NULL CHECK(snapshot_type IN('runtime_created','day_open','periodic','day_close','runtime_complete','recovery')),snapshot jsonb NOT NULL,engine_version text NOT NULL,formula_version text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.festival_runtime_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),runtime_session_id uuid REFERENCES public.festival_runtime_sessions(id),actor_profile_id uuid REFERENCES public.profiles(id),action text NOT NULL,idempotency_key uuid NOT NULL,payload_hash text NOT NULL,status text NOT NULL DEFAULT 'processing',result jsonb,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,UNIQUE(actor_profile_id,action,idempotency_key));
CREATE TABLE public.festival_runtime_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),runtime_session_id uuid NOT NULL REFERENCES public.festival_runtime_sessions(id),actor_profile_id uuid REFERENCES public.profiles(id),action text NOT NULL,entity_type text,entity_id uuid,expected_version integer,idempotency_key uuid,payload_hash text NOT NULL,safe_metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());

CREATE FUNCTION public._festival_runtime_actor() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT public._caller_profile_id()$$;
CREATE FUNCTION public._festival_runtime_owner(s uuid,a uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT EXISTS(SELECT 1 FROM public.festival_runtime_sessions r JOIN public.festival_launches l ON l.id=r.festival_launch_id JOIN public.festival_companies c ON c.id=l.festival_company_id WHERE r.id=s AND c.owner_profile_id=a) OR coalesce(public.has_role(auth.uid(),'admin'::public.app_role),false)$$;
CREATE FUNCTION public._festival_runtime_receipt(s public.festival_runtime_sessions) RETURNS jsonb LANGUAGE sql STABLE AS $$SELECT jsonb_build_object('id',s.id,'festivalLaunchId',s.festival_launch_id,'status',s.status,'version',s.version,'gatesOpen',s.gates_open,'siteCapacity',s.site_capacity,'engineVersion',s.engine_version,'formulaVersion',s.formula_version)$$;
CREATE FUNCTION public._festival_runtime_event(s uuid,t text,e uuid,p jsonb DEFAULT '{}',q jsonb DEFAULT '{}',d text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$BEGIN INSERT INTO public.festival_runtime_events(runtime_session_id,event_type,entity_id,public_payload,private_payload,dedupe_key)VALUES(s,t,e,p,q,coalesce(d,t||':'||coalesce(e::text,gen_random_uuid()::text))) ON CONFLICT DO NOTHING;END$$;

CREATE FUNCTION public.prepare_festival_runtime(p_festival_launch_id uuid,p_expected_launch_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE a uuid:=public._festival_runtime_actor();l public.festival_launches%ROWTYPE; snap public.festival_launch_snapshots%ROWTYPE;r public.festival_runtime_sessions%ROWTYPE; req public.festival_runtime_requests%ROWTYPE; h text:=encode(digest(p_festival_launch_id::text||':'||p_expected_launch_version::text,'sha256'),'hex'); seed text; ed public.festival_public_editions%ROWTYPE;
BEGIN
 SELECT * INTO l FROM public.festival_launches WHERE id=p_festival_launch_id FOR UPDATE; IF l.id IS NULL OR NOT public._festival_launch_authorised(l.festival_company_id,a) THEN RAISE EXCEPTION 'festival_runtime_forbidden'; END IF;
 SELECT * INTO r FROM public.festival_runtime_sessions WHERE festival_launch_id=l.id; IF r.id IS NOT NULL THEN RETURN public._festival_runtime_receipt(r)||jsonb_build_object('idempotent',true); END IF;
 IF l.launch_version<>p_expected_launch_version THEN RAISE EXCEPTION 'festival_runtime_stale_launch'; END IF; IF l.launch_status NOT IN('launched','tickets_on_sale','sales_paused','sales_closed') OR l.cancelled_at IS NOT NULL THEN RAISE EXCEPTION 'festival_runtime_launch_invalid'; END IF;
 SELECT * INTO snap FROM public.festival_launch_snapshots WHERE festival_launch_id=l.id AND snapshot_version=l.launch_version; IF snap.id IS NULL THEN RAISE EXCEPTION 'festival_runtime_snapshot_missing'; END IF;
 SELECT * INTO ed FROM public.festival_public_editions WHERE festival_launch_id=l.id; seed:=encode(hmac(l.id::text||':'||snap.id::text||':'||clock_timestamp()::text,encode(gen_random_bytes(32),'hex'),'sha256'),'hex');
 INSERT INTO public.festival_runtime_sessions(festival_launch_id,launch_snapshot_id,status,runtime_seed,attendance_seed,operations_seed,incident_seed,site_capacity) VALUES(l.id,snap.id,'pre_event',seed,encode(digest(seed||':attendance','sha256'),'hex'),encode(digest(seed||':operations','sha256'),'hex'),encode(digest(seed||':incidents','sha256'),'hex'),coalesce((snap.site_snapshot->>'usableCapacity')::integer,(SELECT max(capacity) FROM public.festival_ticket_inventory i WHERE i.festival_launch_id=l.id),0)) RETURNING * INTO r;
 INSERT INTO public.festival_runtime_requests(runtime_session_id,actor_profile_id,action,idempotency_key,payload_hash,status)VALUES(r.id,a,'prepare_festival_runtime',p_idempotency_key,h,'processing');
 INSERT INTO public.festival_runtime_days(runtime_session_id,festival_date,day_number,starts_at,ends_at,day_seed) SELECT r.id,d::date,row_number() over(order by d),greatest(ed.starts_at,d),least(ed.ends_at,d+interval '1 day'),encode(digest(seed||':day:'||d::text,'sha256'),'hex') FROM generate_series(date_trunc('day',ed.starts_at),date_trunc('day',ed.ends_at),interval '1 day') d WHERE greatest(ed.starts_at,d)<least(ed.ends_at,d+interval '1 day');
 INSERT INTO public.festival_runtime_stages(runtime_session_id,source_stage_id,stage_name,capacity,stage_seed) SELECT r.id,s.source_stage_id,s.name,s.capacity,encode(digest(seed||':stage:'||s.source_stage_id::text,'sha256'),'hex') FROM public.festival_public_stages s WHERE s.festival_launch_id=l.id;
 INSERT INTO public.festival_runtime_performances(runtime_session_id,runtime_day_id,runtime_stage_id,source_timetable_id,solo_artist_profile_id,band_id,npc_artist_id,artist_name,scheduled_start,scheduled_end,performance_seed,engine_version,formula_version) SELECT r.id,d.id,st.id,t.id,CASE WHEN t.artist_type='player' THEN t.artist_id END,CASE WHEN t.artist_type='band' THEN t.artist_id END,CASE WHEN t.artist_type='npc' THEN t.artist_id END,t.artist_name,t.starts_at,t.ends_at,encode(digest(seed||':performance:'||t.id::text,'sha256'),'hex'),r.engine_version,r.formula_version FROM public.festival_public_timetable t JOIN public.festival_runtime_days d ON d.runtime_session_id=r.id AND d.festival_date=t.festival_date JOIN public.festival_runtime_stages st ON st.runtime_session_id=r.id AND st.source_stage_id=(SELECT source_stage_id FROM public.festival_public_stages WHERE id=t.stage_id) WHERE t.festival_launch_id=l.id;
 INSERT INTO public.festival_runtime_artist_checkins(runtime_performance_id,expected_at) SELECT id,scheduled_start-interval '90 minutes' FROM public.festival_runtime_performances WHERE runtime_session_id=r.id;
 INSERT INTO public.festival_runtime_gate_sessions(runtime_session_id,runtime_day_id,opens_at,closes_at) SELECT r.id,id,starts_at,ends_at FROM public.festival_runtime_days WHERE runtime_session_id=r.id;
 INSERT INTO public.festival_runtime_attendance(runtime_session_id,runtime_day_id,capacity) SELECT r.id,id,r.site_capacity FROM public.festival_runtime_days WHERE runtime_session_id=r.id;
 INSERT INTO public.festival_runtime_jobs(runtime_session_id,runtime_day_id,job_type,run_at,dedupe_key) SELECT r.id,id,x.kind,CASE x.kind WHEN 'start_site_setup' THEN starts_at-interval '12 hours' WHEN 'open_gates' THEN starts_at WHEN 'close_gates' THEN ends_at ELSE ends_at+interval '1 hour' END,x.kind||':'||id FROM public.festival_runtime_days CROSS JOIN (VALUES('start_site_setup'),('evaluate_gate_readiness'),('open_gates'),('close_gates'),('refresh_runtime_summary')) x(kind) WHERE runtime_session_id=r.id;
 INSERT INTO public.festival_runtime_jobs(runtime_session_id,runtime_day_id,runtime_stage_id,runtime_performance_id,job_type,run_at,dedupe_key) SELECT r.id,p.runtime_day_id,p.runtime_stage_id,p.id,x.kind,CASE x.kind WHEN 'prepare_stage' THEN p.scheduled_start-interval '30 minutes' WHEN 'start_performance' THEN p.scheduled_start ELSE p.scheduled_end END,x.kind||':'||p.id FROM public.festival_runtime_performances p CROSS JOIN (VALUES('prepare_stage'),('start_performance'),('resolve_performance'),('start_changeover'),('complete_changeover')) x(kind) WHERE p.runtime_session_id=r.id;
 INSERT INTO public.festival_runtime_snapshots(runtime_session_id,snapshot_type,snapshot,engine_version,formula_version)VALUES(r.id,'runtime_created',jsonb_build_object('launchSnapshotId',snap.id,'status',r.status,'runtimeSeed',seed),r.engine_version,r.formula_version);
 PERFORM public._festival_runtime_event(r.id,'runtime_created',r.id,jsonb_build_object('status','pre_event'),'{}','runtime_created'); INSERT INTO public.festival_runtime_audit(runtime_session_id,actor_profile_id,action,entity_type,entity_id,expected_version,idempotency_key,payload_hash)VALUES(r.id,a,'prepare_festival_runtime','runtime_session',r.id,p_expected_launch_version,p_idempotency_key,h); UPDATE public.festival_runtime_requests SET status='completed',completed_at=now(),result=public._festival_runtime_receipt(r) WHERE runtime_session_id=r.id AND idempotency_key=p_idempotency_key; RETURN public._festival_runtime_receipt(r)||jsonb_build_object('idempotent',false);
END$$;

CREATE FUNCTION public._festival_runtime_transition(p_session uuid,p_expected integer,p_key uuid,p_from text[],p_to text,p_event text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE a uuid:=public._festival_runtime_actor();r public.festival_runtime_sessions%ROWTYPE;h text:=encode(digest(p_session::text||':'||p_to,'sha256'),'hex');old text;BEGIN SELECT * INTO r FROM public.festival_runtime_sessions WHERE id=p_session FOR UPDATE;IF NOT public._festival_runtime_owner(p_session,a) THEN RAISE EXCEPTION 'festival_runtime_forbidden';END IF;IF r.version<>p_expected THEN RAISE EXCEPTION 'festival_runtime_stale';END IF;IF NOT r.status=ANY(p_from) THEN RAISE EXCEPTION 'festival_runtime_transition_invalid';END IF;old:=r.status;UPDATE public.festival_runtime_sessions SET status=p_to,status_before_hold=CASE WHEN p_to IN('paused','emergency_hold') THEN old ELSE status_before_hold END,gates_open=CASE WHEN p_to IN('public_closed','site_clearance','runtime_complete') THEN false ELSE gates_open END,version=version+1,updated_at=now(),completed_at=CASE WHEN p_to='runtime_complete' THEN now() END WHERE id=p_session RETURNING * INTO r;PERFORM public._festival_runtime_event(p_session,p_event,p_session,CASE WHEN p_event='emergency_hold' THEN jsonb_build_object('message','The Festival schedule is temporarily paused.') ELSE jsonb_build_object('status',p_to) END,jsonb_build_object('previousStatus',old),p_event||':'||r.version);INSERT INTO public.festival_runtime_audit(runtime_session_id,actor_profile_id,action,entity_type,entity_id,expected_version,idempotency_key,payload_hash)VALUES(p_session,a,p_event,'runtime_session',p_session,p_expected,p_key,h);RETURN public._festival_runtime_receipt(r);END$$;
CREATE FUNCTION public.start_festival_site_setup(p_runtime_session_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$SELECT public._festival_runtime_transition(p_runtime_session_id,p_expected_version,p_idempotency_key,ARRAY['pre_event'],'site_setup','site_setup_started')$$;
CREATE FUNCTION public.mark_festival_ready_to_open(p_runtime_session_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE blockers jsonb;r jsonb;BEGIN SELECT coalesce(jsonb_agg(x),'[]') INTO blockers FROM (SELECT 'safety_critical_staff_missing' x FROM public.festival_runtime_staff_checkins WHERE runtime_session_id=p_runtime_session_id AND safety_critical AND status NOT IN('checked_in','late') UNION ALL SELECT 'essential_supplier_missing' FROM public.festival_runtime_supplier_checkins WHERE runtime_session_id=p_runtime_session_id AND essential AND status NOT IN('arrived','late'))q;IF jsonb_array_length(blockers)>0 THEN UPDATE public.festival_runtime_gate_sessions SET blocking_failures=blockers WHERE runtime_session_id=p_runtime_session_id;RAISE EXCEPTION 'festival_gate_blocked';END IF;UPDATE public.festival_runtime_sessions SET setup_complete=true WHERE id=p_runtime_session_id;SELECT public._festival_runtime_transition(p_runtime_session_id,p_expected_version,p_idempotency_key,ARRAY['site_setup'],'ready_to_open','runtime_ready_to_open') INTO r;RETURN r;END$$;
CREATE FUNCTION public.open_festival_gates(p_runtime_session_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE r jsonb;BEGIN IF EXISTS(SELECT 1 FROM public.festival_runtime_sessions WHERE id=p_runtime_session_id AND (NOT setup_complete OR NOT ticket_system_available OR admissions_paused)) THEN RAISE EXCEPTION 'festival_gate_blocked';END IF;SELECT public._festival_runtime_transition(p_runtime_session_id,p_expected_version,p_idempotency_key,ARRAY['ready_to_open'],'gates_open','gates_opened') INTO r;UPDATE public.festival_runtime_sessions SET gates_open=true,status='live' WHERE id=p_runtime_session_id;UPDATE public.festival_runtime_gate_sessions SET status='open',version=version+1 WHERE runtime_session_id=p_runtime_session_id AND current_date=(SELECT festival_date FROM public.festival_runtime_days WHERE id=runtime_day_id);RETURN r||jsonb_build_object('status','live','gatesOpen',true);END$$;
CREATE FUNCTION public.close_festival_gates(p_runtime_session_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE r public.festival_runtime_sessions%ROWTYPE;BEGIN IF NOT public._festival_runtime_owner(p_runtime_session_id,public._festival_runtime_actor()) THEN RAISE EXCEPTION 'festival_runtime_forbidden';END IF;UPDATE public.festival_runtime_sessions SET gates_open=false,version=version+1 WHERE id=p_runtime_session_id AND version=p_expected_version RETURNING * INTO r;IF r.id IS NULL THEN RAISE EXCEPTION 'festival_runtime_stale';END IF;UPDATE public.festival_runtime_gate_sessions SET status='closed',version=version+1 WHERE runtime_session_id=p_runtime_session_id;PERFORM public._festival_runtime_event(r.id,'gates_closed',r.id,jsonb_build_object('gatesOpen',false),'{}','gates_closed:'||r.version);RETURN public._festival_runtime_receipt(r);END$$;
CREATE FUNCTION public.admit_festival_ticket(p_runtime_session_id uuid,p_issued_ticket_id uuid,p_gate_reference text,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE a uuid:=public._festival_runtime_actor();r public.festival_runtime_sessions%ROWTYPE;t public.festival_issued_tickets%ROWTYPE;d public.festival_runtime_days%ROWTYPE;ad public.festival_runtime_ticket_admissions%ROWTYPE;BEGIN SELECT * INTO r FROM public.festival_runtime_sessions WHERE id=p_runtime_session_id FOR UPDATE;IF r.status<>'live' OR NOT r.gates_open OR r.admissions_paused THEN RAISE EXCEPTION 'festival_admission_gates_closed';END IF;SELECT * INTO t FROM public.festival_issued_tickets WHERE id=p_issued_ticket_id FOR UPDATE;IF t.id IS NULL OR t.holder_profile_id<>a OR t.status NOT IN('valid','used') OR NOT EXISTS(SELECT 1 FROM public.festival_public_ticket_products p WHERE p.id=t.ticket_product_id AND p.festival_launch_id=r.festival_launch_id AND p.product_class='admission' AND p.access_scope<>'non_admission') THEN RAISE EXCEPTION 'festival_ticket_invalid';END IF;SELECT * INTO d FROM public.festival_runtime_days WHERE runtime_session_id=r.id AND festival_date=current_date;IF d.id IS NULL OR current_date NOT BETWEEN t.access_start_date AND t.access_end_date THEN RAISE EXCEPTION 'festival_ticket_wrong_date';END IF;SELECT * INTO ad FROM public.festival_runtime_ticket_admissions WHERE runtime_session_id=r.id AND idempotency_key=p_idempotency_key;IF ad.id IS NOT NULL THEN RETURN jsonb_build_object('admissionId',ad.id,'idempotent',true);END IF;UPDATE public.festival_runtime_attendance SET admitted_count=admitted_count+1,version=version+1,updated_at=now() WHERE runtime_day_id=d.id AND onsite_count<capacity;IF NOT FOUND THEN RAISE EXCEPTION 'festival_site_at_capacity';END IF;INSERT INTO public.festival_runtime_ticket_admissions(runtime_session_id,runtime_day_id,issued_ticket_id,gate_reference,admitted_by_profile_id,idempotency_key)VALUES(r.id,d.id,t.id,left(btrim(p_gate_reference),100),a,p_idempotency_key) RETURNING * INTO ad;UPDATE public.festival_issued_tickets SET status=CASE WHEN access_end_date=current_date THEN 'used' ELSE status END,used_at=coalesce(used_at,now()) WHERE id=t.id;PERFORM public._festival_runtime_event(r.id,'ticket_admitted',ad.id,jsonb_build_object('attendanceBand',(SELECT CASE WHEN onsite_count>=capacity THEN 'full' WHEN onsite_count>=capacity*.9 THEN 'near_capacity' WHEN onsite_count>=capacity*.7 THEN 'very_busy' WHEN onsite_count>=capacity*.4 THEN 'busy' WHEN onsite_count>=capacity*.15 THEN 'building' ELSE 'quiet' END FROM public.festival_runtime_attendance WHERE runtime_day_id=d.id)),'{}','ticket_admitted:'||ad.id);RETURN jsonb_build_object('admissionId',ad.id,'runtimeDayId',d.id,'idempotent',false);EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'festival_ticket_already_admitted';END$$;

CREATE FUNCTION public.check_in_festival_artist(p_runtime_performance_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE a uuid:=public._festival_runtime_actor();p public.festival_runtime_performances%ROWTYPE;c public.festival_runtime_artist_checkins%ROWTYPE;BEGIN SELECT * INTO p FROM public.festival_runtime_performances WHERE id=p_runtime_performance_id FOR UPDATE;IF p.version<>p_expected_version OR p.status IN('completed','cancelled','failed') THEN RAISE EXCEPTION 'festival_performance_stale';END IF;IF p.solo_artist_profile_id IS DISTINCT FROM a AND NOT public._festival_runtime_owner(p.runtime_session_id,a) THEN RAISE EXCEPTION 'festival_artist_forbidden';END IF;IF now()<p.scheduled_start-interval '6 hours' OR now()>p.scheduled_end THEN RAISE EXCEPTION 'festival_artist_arrival_window';END IF;UPDATE public.festival_runtime_artist_checkins SET status=CASE WHEN now()>expected_at THEN 'late' ELSE 'checked_in' END,checked_in_by_profile_id=a,checked_in_at=now(),version=version+1 WHERE runtime_performance_id=p.id AND status='expected' RETURNING * INTO c;IF c.id IS NULL THEN RAISE EXCEPTION 'festival_artist_already_checked_in';END IF;UPDATE public.festival_runtime_performances SET status='artist_ready',version=version+1 WHERE id=p.id;PERFORM public._festival_runtime_event(p.runtime_session_id,'artist_checked_in',p.id,'{}',jsonb_build_object('status',c.status),'artist_checked_in:'||p.id);RETURN to_jsonb(c);END$$;
CREATE FUNCTION public.check_in_festival_band_member(p_runtime_performance_id uuid,p_member_profile_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE a uuid:=public._festival_runtime_actor();p public.festival_runtime_performances%ROWTYPE;m public.festival_runtime_band_member_attendance%ROWTYPE;BEGIN SELECT * INTO p FROM public.festival_runtime_performances WHERE id=p_runtime_performance_id FOR UPDATE;IF p.band_id IS NULL OR p.version<>p_expected_version THEN RAISE EXCEPTION 'festival_performance_stale';END IF;IF a<>p_member_profile_id AND NOT public._festival_runtime_owner(p.runtime_session_id,a) THEN RAISE EXCEPTION 'festival_band_authority_required';END IF;INSERT INTO public.festival_runtime_band_member_attendance(runtime_performance_id,profile_id,status,checked_in_at)VALUES(p.id,p_member_profile_id,CASE WHEN now()>p.scheduled_start-interval '60 minutes' THEN 'late' ELSE 'present' END,now()) ON CONFLICT(runtime_performance_id,profile_id) DO NOTHING RETURNING * INTO m;IF m.id IS NULL THEN RAISE EXCEPTION 'festival_band_member_already_checked_in';END IF;RETURN to_jsonb(m);END$$;

CREATE FUNCTION public.check_in_festival_staff(p_runtime_session_id uuid,p_staff_shift_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE a uuid:=public._festival_runtime_actor();s public.festival_staff_shifts%ROWTYPE;x public.festival_staff_assignments%ROWTYPE;c public.festival_runtime_staff_checkins%ROWTYPE;BEGIN SELECT * INTO s FROM public.festival_staff_shifts WHERE id=p_staff_shift_id;SELECT * INTO x FROM public.festival_staff_assignments WHERE id=s.staff_assignment_id;IF x.profile_id IS DISTINCT FROM a OR now() NOT BETWEEN s.starts_at-interval '2 hours' AND s.ends_at THEN RAISE EXCEPTION 'festival_staff_checkin_forbidden';END IF;IF EXISTS(SELECT 1 FROM public.festival_runtime_staff_checkins WHERE profile_id=a AND status IN('checked_in','late') AND staff_shift_id<>s.id) THEN RAISE EXCEPTION 'festival_staff_overlapping_shift';END IF;INSERT INTO public.festival_runtime_staff_checkins(runtime_session_id,staff_shift_id,profile_id,status,safety_critical,expected_start,expected_end,checked_in_at) SELECT p_runtime_session_id,s.id,a,CASE WHEN now()>s.starts_at THEN 'late' ELSE 'checked_in' END,r.safety_critical,s.starts_at,s.ends_at,now() FROM public.festival_staffing_requirements r WHERE r.id=x.staffing_requirement_id ON CONFLICT(staff_shift_id) DO NOTHING RETURNING * INTO c;IF c.id IS NULL THEN RAISE EXCEPTION 'festival_staff_already_checked_in';END IF;PERFORM public._festival_runtime_event(p_runtime_session_id,'staff_checked_in',c.id,'{}',jsonb_build_object('role',x.role_type),'staff_checked_in:'||c.id);RETURN to_jsonb(c);END$$;
CREATE FUNCTION public.check_out_festival_staff(p_runtime_session_id uuid,p_staff_shift_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE a uuid:=public._festival_runtime_actor();c public.festival_runtime_staff_checkins%ROWTYPE;BEGIN UPDATE public.festival_runtime_staff_checkins SET status='checked_out',checked_out_at=now(),version=version+1 WHERE runtime_session_id=p_runtime_session_id AND staff_shift_id=p_staff_shift_id AND profile_id=a AND version=p_expected_version AND status IN('checked_in','late') RETURNING * INTO c;IF c.id IS NULL THEN RAISE EXCEPTION 'festival_staff_checkout_invalid';END IF;RETURN to_jsonb(c);END$$;
CREATE FUNCTION public.check_in_festival_supplier(p_runtime_session_id uuid,p_supplier_contract_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE a uuid:=public._festival_runtime_actor();x public.festival_supplier_contracts%ROWTYPE;c public.festival_runtime_supplier_checkins%ROWTYPE;BEGIN SELECT * INTO x FROM public.festival_supplier_contracts WHERE id=p_supplier_contract_id;IF x.status NOT IN('committed','awaiting_delivery','active') OR (x.supplier_company_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.companies WHERE id=x.supplier_company_id AND owner_id=auth.uid())) AND NOT public._festival_runtime_owner(p_runtime_session_id,a) THEN RAISE EXCEPTION 'festival_supplier_forbidden';END IF;INSERT INTO public.festival_runtime_supplier_checkins(runtime_session_id,supplier_contract_id,supplier_company_id,npc_supplier_id,status,essential,delivery_start,delivery_end,arrived_at) SELECT p_runtime_session_id,x.id,x.supplier_company_id,x.npc_supplier_id,CASE WHEN now()>x.delivery_end THEN 'late' ELSE 'arrived' END,r.safety_critical,x.delivery_start,x.delivery_end,now() FROM public.festival_supplier_requirements r WHERE r.id=x.supplier_requirement_id ON CONFLICT(supplier_contract_id) DO NOTHING RETURNING * INTO c;IF c.id IS NULL THEN RAISE EXCEPTION 'festival_supplier_already_arrived';END IF;PERFORM public._festival_runtime_event(p_runtime_session_id,'supplier_arrived',c.id,'{}',jsonb_build_object('late',c.status='late'),'supplier_arrived:'||c.id);RETURN to_jsonb(c);END$$;
CREATE FUNCTION public.check_out_festival_supplier(p_runtime_session_id uuid,p_supplier_contract_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE c public.festival_runtime_supplier_checkins%ROWTYPE;BEGIN UPDATE public.festival_runtime_supplier_checkins SET status='departed',departed_at=now(),version=version+1 WHERE runtime_session_id=p_runtime_session_id AND supplier_contract_id=p_supplier_contract_id AND version=p_expected_version AND status IN('arrived','late') RETURNING * INTO c;IF c.id IS NULL THEN RAISE EXCEPTION 'festival_supplier_checkout_invalid';END IF;RETURN to_jsonb(c);END$$;
CREATE FUNCTION public.mark_festival_stage_ready(p_runtime_stage_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE st public.festival_runtime_stages%ROWTYPE;a uuid:=public._festival_runtime_actor();BEGIN SELECT * INTO st FROM public.festival_runtime_stages WHERE id=p_runtime_stage_id FOR UPDATE;IF st.version<>p_expected_version OR NOT public._festival_runtime_owner(st.runtime_session_id,a) THEN RAISE EXCEPTION 'festival_stage_forbidden_or_stale';END IF;UPDATE public.festival_runtime_stages SET status='ready',safety_ready=true,crew_ready=true,version=version+1 WHERE id=st.id RETURNING * INTO st;UPDATE public.festival_runtime_performances SET status=CASE WHEN status='artist_ready' THEN 'ready' ELSE 'stage_ready' END,version=version+1 WHERE runtime_stage_id=st.id AND status IN('scheduled','awaiting_artist','artist_ready');PERFORM public._festival_runtime_event(st.runtime_session_id,'stage_ready',st.id,jsonb_build_object('stageName',st.stage_name),'{}','stage_ready:'||st.id||':'||st.version);RETURN to_jsonb(st);END$$;
CREATE FUNCTION public.start_festival_performance(p_runtime_performance_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE p public.festival_runtime_performances%ROWTYPE;s public.festival_runtime_sessions%ROWTYPE;st public.festival_runtime_stages%ROWTYPE;input jsonb;BEGIN SELECT * INTO p FROM public.festival_runtime_performances WHERE id=p_runtime_performance_id FOR UPDATE;SELECT * INTO s FROM public.festival_runtime_sessions WHERE id=p.runtime_session_id FOR UPDATE;SELECT * INTO st FROM public.festival_runtime_stages WHERE id=p.runtime_stage_id FOR UPDATE;IF NOT public._festival_runtime_owner(s.id,public._festival_runtime_actor()) OR p.version<>p_expected_version THEN RAISE EXCEPTION 'festival_performance_forbidden_or_stale';END IF;IF s.status<>'live' OR st.status<>'ready' OR NOT st.safety_ready OR NOT st.crew_ready OR NOT EXISTS(SELECT 1 FROM public.festival_runtime_artist_checkins WHERE runtime_performance_id=p.id AND status IN('checked_in','late','waived')) OR EXISTS(SELECT 1 FROM public.festival_runtime_band_member_attendance WHERE runtime_performance_id=p.id AND required AND status NOT IN('present','late','substituted','excused')) OR now() NOT BETWEEN p.scheduled_start-interval '30 minutes' AND p.scheduled_end THEN RAISE EXCEPTION 'festival_performance_not_ready';END IF;input:=jsonb_build_object('adapter','festival-gig-adapter-v1','canonicalEngine',s.engine_version,'seed',p.performance_seed,'artist',jsonb_build_object('name',p.artist_name,'soloArtistId',p.solo_artist_profile_id,'bandId',p.band_id,'npcArtistId',p.npc_artist_id),'schedule',jsonb_build_object('startsAt',p.scheduled_start,'endsAt',p.scheduled_end),'festivalModifiers',jsonb_build_object('stageCapacity',st.capacity,'delayPressure',p.delay_minutes));UPDATE public.festival_runtime_performances SET status='live',actual_start=now(),engine_input_snapshot=input,version=version+1 WHERE id=p.id AND engine_input_snapshot IS NULL RETURNING * INTO p;IF p.id IS NULL THEN RAISE EXCEPTION 'festival_performance_already_started';END IF;UPDATE public.festival_runtime_stages SET status='performance_live',version=version+1 WHERE id=st.id;PERFORM public._festival_runtime_event(s.id,'performance_started',p.id,jsonb_build_object('artistName',p.artist_name,'stageName',st.stage_name),'{}','performance_started:'||p.id);RETURN to_jsonb(p);END$$;
CREATE FUNCTION public.resolve_festival_performance(p_runtime_performance_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE p public.festival_runtime_performances%ROWTYPE;score integer;result jsonb;BEGIN SELECT * INTO p FROM public.festival_runtime_performances WHERE id=p_runtime_performance_id FOR UPDATE;IF NOT public._festival_runtime_owner(p.runtime_session_id,public._festival_runtime_actor()) OR p.version<>p_expected_version THEN RAISE EXCEPTION 'festival_performance_forbidden_or_stale';END IF;IF p.status='completed' THEN RETURN to_jsonb(p);END IF;IF p.status<>'live' OR p.engine_input_snapshot IS NULL OR p.engine_result_snapshot IS NOT NULL THEN RAISE EXCEPTION 'festival_performance_resolution_invalid';END IF;
 -- Thin SQL boundary to the canonical gig formula version. Inputs are frozen at start;
 -- this phase stores preliminary runtime metrics only and awards nothing.
 score:=45+(('x'||substr(p.performance_seed,1,8))::bit(32)::bigint%51);result:=jsonb_build_object('canonicalGigEngineVersion',p.engine_version,'adapterVersion','festival-gig-adapter-v1','performanceScore',score,'technicalScore',greatest(0,score-5),'setlistScore',score,'artistScore',least(100,score+3),'crowdResponse',CASE WHEN score>=80 THEN 'excellent' WHEN score>=60 THEN 'good' ELSE 'mixed' END,'estimatedAudience',0,'delayImpact',least(50,p.delay_minutes));UPDATE public.festival_runtime_performances SET status='completed',actual_end=now(),engine_result_snapshot=result,performance_score=score,technical_score=greatest(0,score-5),setlist_score=score,artist_score=least(100,score+3),crowd_response=result->>'crowdResponse',estimated_audience=0,delay_impact=least(50,p.delay_minutes),version=version+1 WHERE id=p.id AND engine_result_snapshot IS NULL RETURNING * INTO p;IF p.id IS NULL THEN RAISE EXCEPTION 'festival_performance_already_resolved';END IF;UPDATE public.festival_runtime_stages SET status='changeover',version=version+1 WHERE id=p.runtime_stage_id;PERFORM public._festival_runtime_event(p.runtime_session_id,'performance_completed',p.id,jsonb_build_object('artistName',p.artist_name,'performanceScore',score),'{}','performance_completed:'||p.id);RETURN to_jsonb(p);END$$;
CREATE FUNCTION public.record_festival_performance_delay(p_runtime_performance_id uuid,p_expected_version integer,p_delay_minutes integer,p_reason text,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE p public.festival_runtime_performances%ROWTYPE;BEGIN IF p_reason NOT IN('artist_late','technical_issue','previous_performance_overrun','changeover_delay','weather_hold','safety_hold','staffing_issue','supplier_issue','admin_adjustment') OR p_delay_minutes NOT BETWEEN 1 AND 240 THEN RAISE EXCEPTION 'festival_delay_invalid';END IF;UPDATE public.festival_runtime_performances SET status='delayed',delay_minutes=delay_minutes+p_delay_minutes,version=version+1 WHERE id=p_runtime_performance_id AND version=p_expected_version AND status NOT IN('completed','cancelled','failed') RETURNING * INTO p;IF p.id IS NULL OR NOT public._festival_runtime_owner(p.runtime_session_id,public._festival_runtime_actor()) THEN RAISE EXCEPTION 'festival_performance_forbidden_or_stale';END IF;PERFORM public._festival_runtime_event(p.runtime_session_id,'performance_delayed',p.id,jsonb_build_object('delayMinutes',p.delay_minutes,'reason',p_reason),jsonb_build_object('reason',p_reason),'performance_delayed:'||p.id||':'||p.version);RETURN to_jsonb(p);END$$;
CREATE FUNCTION public.cancel_runtime_festival_performance(p_runtime_performance_id uuid,p_expected_version integer,p_reason text,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE p public.festival_runtime_performances%ROWTYPE;BEGIN SELECT * INTO p FROM public.festival_runtime_performances WHERE id=p_runtime_performance_id FOR UPDATE;IF p.version<>p_expected_version OR p.status='completed' OR NOT public._festival_runtime_owner(p.runtime_session_id,public._festival_runtime_actor()) THEN RAISE EXCEPTION 'festival_performance_cancel_invalid';END IF;UPDATE public.festival_runtime_performances SET status='cancelled',version=version+1 WHERE id=p.id RETURNING * INTO p;PERFORM public._festival_runtime_event(p.runtime_session_id,'performance_cancelled',p.id,jsonb_build_object('artistName',p.artist_name,'message','Performance cancelled'),jsonb_build_object('reason',left(p_reason,500)),'performance_cancelled:'||p.id);RETURN to_jsonb(p);END$$;
CREATE FUNCTION public.pause_festival_runtime(p_runtime_session_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$SELECT public._festival_runtime_transition(p_runtime_session_id,p_expected_version,p_idempotency_key,ARRAY['site_setup','ready_to_open','gates_open','live'],'paused','runtime_paused')$$;
CREATE FUNCTION public.resume_festival_runtime(p_runtime_session_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE r public.festival_runtime_sessions%ROWTYPE;BEGIN SELECT * INTO r FROM public.festival_runtime_sessions WHERE id=p_runtime_session_id;IF r.status NOT IN('paused','emergency_hold') OR EXISTS(SELECT 1 FROM public.festival_runtime_staff_checkins WHERE runtime_session_id=r.id AND safety_critical AND status NOT IN('checked_in','late')) THEN RAISE EXCEPTION 'festival_runtime_resume_blocked';END IF;RETURN public._festival_runtime_transition(p_runtime_session_id,p_expected_version,p_idempotency_key,ARRAY[r.status],coalesce(r.status_before_hold,'site_setup'),'runtime_resumed');END$$;
CREATE FUNCTION public.place_festival_emergency_hold(p_runtime_session_id uuid,p_expected_version integer,p_pause_admissions boolean,p_private_reason text,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE out jsonb;BEGIN SELECT public._festival_runtime_transition(p_runtime_session_id,p_expected_version,p_idempotency_key,ARRAY['site_setup','ready_to_open','gates_open','live','paused'],'emergency_hold','emergency_hold') INTO out;UPDATE public.festival_runtime_sessions SET admissions_paused=p_pause_admissions WHERE id=p_runtime_session_id;UPDATE public.festival_runtime_jobs SET status='paused' WHERE runtime_session_id=p_runtime_session_id AND status='pending' AND job_type IN('open_gates','start_performance');RETURN out;END$$;
CREATE FUNCTION public.clear_festival_emergency_hold(p_runtime_session_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE out jsonb;BEGIN SELECT public.resume_festival_runtime(p_runtime_session_id,p_expected_version,p_idempotency_key) INTO out;UPDATE public.festival_runtime_sessions SET admissions_paused=false WHERE id=p_runtime_session_id;UPDATE public.festival_runtime_jobs SET status='pending' WHERE runtime_session_id=p_runtime_session_id AND status='paused';PERFORM public._festival_runtime_event(p_runtime_session_id,'emergency_cleared',p_runtime_session_id,jsonb_build_object('status',out->>'status'),'{}','emergency_cleared:'||(out->>'version'));RETURN out;END$$;
CREATE FUNCTION public.complete_festival_public_close(p_runtime_session_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$SELECT public._festival_runtime_transition(p_runtime_session_id,p_expected_version,p_idempotency_key,ARRAY['live','final_performance_complete'],'public_closed','public_closed')$$;
CREATE FUNCTION public.complete_festival_site_clearance(p_runtime_session_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$SELECT public._festival_runtime_transition(p_runtime_session_id,p_expected_version,p_idempotency_key,ARRAY['public_closed','site_clearance'],'site_clearance','site_clearance_started')$$;
CREATE FUNCTION public.complete_festival_runtime(p_runtime_session_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE out jsonb;BEGIN IF EXISTS(SELECT 1 FROM public.festival_runtime_performances WHERE runtime_session_id=p_runtime_session_id AND status NOT IN('completed','cancelled','abandoned','failed')) THEN RAISE EXCEPTION 'festival_runtime_performances_incomplete';END IF;SELECT public._festival_runtime_transition(p_runtime_session_id,p_expected_version,p_idempotency_key,ARRAY['site_clearance'],'runtime_complete','runtime_completed') INTO out;INSERT INTO public.festival_runtime_snapshots(runtime_session_id,snapshot_type,snapshot,engine_version,formula_version)SELECT id,'runtime_complete',public._festival_runtime_receipt(r),engine_version,formula_version FROM public.festival_runtime_sessions r WHERE id=p_runtime_session_id;RETURN out;END$$;
CREATE FUNCTION public.recover_festival_runtime(p_runtime_session_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE r public.festival_runtime_sessions%ROWTYPE;BEGIN SELECT * INTO r FROM public.festival_runtime_sessions WHERE id=p_runtime_session_id FOR UPDATE;IF r.version<>p_expected_version OR NOT public._festival_runtime_owner(r.id,public._festival_runtime_actor()) THEN RAISE EXCEPTION 'festival_runtime_forbidden_or_stale';END IF;UPDATE public.festival_runtime_jobs SET status='pending',locked_at=NULL,locked_by=NULL WHERE runtime_session_id=r.id AND status='claimed' AND locked_at<now()-interval '5 minutes';UPDATE public.festival_runtime_stages st SET status='changeover',version=version+1 WHERE st.runtime_session_id=r.id AND st.status='performance_live' AND EXISTS(SELECT 1 FROM public.festival_runtime_performances p WHERE p.runtime_stage_id=st.id AND p.status='completed');INSERT INTO public.festival_runtime_snapshots(runtime_session_id,snapshot_type,snapshot,engine_version,formula_version)VALUES(r.id,'recovery',public._festival_runtime_receipt(r),r.engine_version,r.formula_version);INSERT INTO public.festival_runtime_audit(runtime_session_id,actor_profile_id,action,entity_type,entity_id,expected_version,idempotency_key,payload_hash)VALUES(r.id,public._festival_runtime_actor(),'recover_festival_runtime','runtime_session',r.id,p_expected_version,p_idempotency_key,encode(digest(r.id::text||':'||p_expected_version,'sha256'),'hex'));RETURN public._festival_runtime_receipt(r);END$$;
CREATE FUNCTION public.process_due_festival_runtime_jobs(p_runtime_session_id uuid DEFAULT NULL,p_limit integer DEFAULT 50) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE j public.festival_runtime_jobs%ROWTYPE;n integer:=0;BEGIN IF auth.role()<>'service_role' AND NOT coalesce(public.has_role(auth.uid(),'admin'::public.app_role),false) THEN RAISE EXCEPTION 'festival_runtime_worker_forbidden';END IF;IF p_limit NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'festival_runtime_job_limit_invalid';END IF;FOR j IN SELECT * FROM public.festival_runtime_jobs WHERE status='pending' AND run_at<=now() AND (p_runtime_session_id IS NULL OR runtime_session_id=p_runtime_session_id) ORDER BY run_at,id FOR UPDATE SKIP LOCKED LIMIT p_limit LOOP UPDATE public.festival_runtime_jobs SET status='claimed',locked_at=now(),locked_by=coalesce(auth.uid()::text,'service_role'),attempts=attempts+1 WHERE id=j.id AND status='pending';IF FOUND THEN UPDATE public.festival_runtime_jobs SET status='completed',completed_at=now(),locked_at=NULL,locked_by=NULL WHERE id=j.id AND status='claimed';n:=n+1;END IF;END LOOP;RETURN jsonb_build_object('processed',n);END$$;

CREATE FUNCTION public.get_festival_runtime(p_runtime_session_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT CASE WHEN public._festival_runtime_owner(r.id,public._festival_runtime_actor()) THEN public._festival_runtime_receipt(r)||jsonb_build_object('days',(SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY day_number),'[]') FROM public.festival_runtime_days d WHERE d.runtime_session_id=r.id),'stages',(SELECT coalesce(jsonb_agg(to_jsonb(s)),'[]') FROM public.festival_runtime_stages s WHERE s.runtime_session_id=r.id),'performances',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY scheduled_start),'[]') FROM public.festival_runtime_performances p WHERE p.runtime_session_id=r.id)) END FROM public.festival_runtime_sessions r WHERE r.id=p_runtime_session_id$$;
CREATE FUNCTION public.get_festival_runtime_owner_dashboard(p_runtime_session_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT public.get_festival_runtime(p_runtime_session_id)||jsonb_build_object('attendance',(SELECT coalesce(jsonb_agg(to_jsonb(a)),'[]') FROM public.festival_runtime_attendance a WHERE a.runtime_session_id=p_runtime_session_id),'artistCheckins',(SELECT coalesce(jsonb_agg(to_jsonb(c)),'[]') FROM public.festival_runtime_artist_checkins c JOIN public.festival_runtime_performances p ON p.id=c.runtime_performance_id WHERE p.runtime_session_id=p_runtime_session_id),'staffCheckins',(SELECT coalesce(jsonb_agg(to_jsonb(c)),'[]') FROM public.festival_runtime_staff_checkins c WHERE c.runtime_session_id=p_runtime_session_id),'supplierCheckins',(SELECT coalesce(jsonb_agg(to_jsonb(c)),'[]') FROM public.festival_runtime_supplier_checkins c WHERE c.runtime_session_id=p_runtime_session_id),'jobs',(SELECT coalesce(jsonb_agg(to_jsonb(j)),'[]') FROM public.festival_runtime_jobs j WHERE j.runtime_session_id=p_runtime_session_id))$$;
CREATE FUNCTION public.get_festival_runtime_stage_dashboard(p_runtime_stage_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT jsonb_build_object('stage',to_jsonb(s),'performances',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY scheduled_start),'[]') FROM public.festival_runtime_performances p WHERE p.runtime_stage_id=s.id)) FROM public.festival_runtime_stages s WHERE s.id=p_runtime_stage_id AND (public._festival_runtime_owner(s.runtime_session_id,public._festival_runtime_actor()) OR EXISTS(SELECT 1 FROM public.festival_stage_manager_assignments m JOIN public.festival_runtime_sessions r ON r.id=s.runtime_session_id JOIN public.festival_launches l ON l.id=r.festival_launch_id WHERE m.festival_timetable_plan_id=l.timetable_plan_id AND m.stage_id=s.source_stage_id AND m.profile_id=public._festival_runtime_actor() AND m.status='assigned'))$$;
CREATE FUNCTION public.get_my_festival_artist_runtime() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT coalesce(jsonb_agg(to_jsonb(p)),'[]') FROM public.festival_runtime_performances p WHERE p.solo_artist_profile_id=public._festival_runtime_actor() OR EXISTS(SELECT 1 FROM public.festival_runtime_band_member_attendance m WHERE m.runtime_performance_id=p.id AND m.profile_id=public._festival_runtime_actor())$$;
CREATE FUNCTION public.get_my_festival_staff_runtime() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT coalesce(jsonb_agg(to_jsonb(c)),'[]') FROM public.festival_runtime_staff_checkins c WHERE c.profile_id=public._festival_runtime_actor()$$;
CREATE FUNCTION public.get_my_festival_supplier_runtime() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT coalesce(jsonb_agg(to_jsonb(c)),'[]') FROM public.festival_runtime_supplier_checkins c WHERE EXISTS(SELECT 1 FROM public.companies x WHERE x.id=c.supplier_company_id AND x.owner_id=auth.uid())$$;
CREATE FUNCTION public.get_public_festival_live_status(p_public_slug text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT jsonb_build_object('festivalLaunchId',r.festival_launch_id,'runtimeStatus',r.status,'gatesStatus',CASE WHEN r.gates_open THEN 'open' ELSE 'closed' END,'currentDay',(SELECT festival_date FROM public.festival_runtime_days WHERE runtime_session_id=r.id AND festival_date=current_date),'attendanceBand',(SELECT CASE WHEN onsite_count>=capacity THEN 'full' WHEN onsite_count>=capacity*.9 THEN 'near_capacity' WHEN onsite_count>=capacity*.7 THEN 'very_busy' WHEN onsite_count>=capacity*.4 THEN 'busy' WHEN onsite_count>=capacity*.15 THEN 'building' ELSE 'quiet' END FROM public.festival_runtime_attendance a JOIN public.festival_runtime_days d ON d.id=a.runtime_day_id WHERE a.runtime_session_id=r.id AND d.festival_date=current_date),'performances',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id,'artistName',p.artist_name,'stageName',s.stage_name,'scheduledStart',p.scheduled_start,'scheduledEnd',p.scheduled_end,'status',p.status,'delayMinutes',p.delay_minutes) ORDER BY p.scheduled_start),'[]') FROM public.festival_runtime_performances p JOIN public.festival_runtime_stages s ON s.id=p.runtime_stage_id WHERE p.runtime_session_id=r.id),'messages',(SELECT coalesce(jsonb_agg(e.public_payload ORDER BY e.created_at),'[]') FROM public.festival_runtime_events e WHERE e.runtime_session_id=r.id AND e.public_payload<>'{}')) FROM public.festival_runtime_sessions r JOIN public.festival_public_editions e ON e.festival_launch_id=r.festival_launch_id WHERE e.slug=p_public_slug$$;
CREATE FUNCTION public.get_festival_runtime_event_log(p_runtime_session_id uuid,p_after timestamptz DEFAULT NULL) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT coalesce(jsonb_agg(jsonb_build_object('id',e.id,'eventType',e.event_type,'entityType',e.entity_type,'entityId',e.entity_id,'publicPayload',e.public_payload,'privatePayload',CASE WHEN public._festival_runtime_owner(e.runtime_session_id,public._festival_runtime_actor()) THEN e.private_payload ELSE '{}' END,'createdAt',e.created_at) ORDER BY e.created_at),'[]') FROM public.festival_runtime_events e WHERE e.runtime_session_id=p_runtime_session_id AND (p_after IS NULL OR e.created_at>p_after) AND (public._festival_runtime_owner(e.runtime_session_id,public._festival_runtime_actor()) OR e.public_payload<>'{}')$$;
-- Runtime state is RPC-only. RLS is defense in depth; no table write grants are made.
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['festival_runtime_sessions','festival_runtime_days','festival_runtime_stages','festival_runtime_performances','festival_runtime_artist_checkins','festival_runtime_band_member_attendance','festival_runtime_staff_checkins','festival_runtime_supplier_checkins','festival_runtime_gate_sessions','festival_runtime_ticket_admissions','festival_runtime_attendance','festival_runtime_jobs','festival_runtime_events','festival_runtime_snapshots','festival_runtime_requests','festival_runtime_audit'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC, anon, authenticated',t);END LOOP;END$$;
REVOKE ALL ON FUNCTION public._festival_runtime_actor(),public._festival_runtime_owner(uuid,uuid),public._festival_runtime_receipt(public.festival_runtime_sessions),public._festival_runtime_event(uuid,text,uuid,jsonb,jsonb,text),public._festival_runtime_transition(uuid,integer,uuid,text[],text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_public_festival_live_status(text) TO anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_festival_runtime(uuid),public.get_festival_runtime_owner_dashboard(uuid),public.get_festival_runtime_stage_dashboard(uuid),public.get_my_festival_artist_runtime(),public.get_my_festival_staff_runtime(),public.get_my_festival_supplier_runtime(),public.get_festival_runtime_event_log(uuid,timestamptz),public.prepare_festival_runtime(uuid,integer,uuid),public.start_festival_site_setup(uuid,integer,uuid),public.check_in_festival_artist(uuid,integer,uuid),public.check_in_festival_band_member(uuid,uuid,integer,uuid),public.check_in_festival_staff(uuid,uuid,integer,uuid),public.check_out_festival_staff(uuid,uuid,integer,uuid),public.check_in_festival_supplier(uuid,uuid,integer,uuid),public.check_out_festival_supplier(uuid,uuid,integer,uuid),public.mark_festival_ready_to_open(uuid,integer,uuid),public.open_festival_gates(uuid,integer,uuid),public.admit_festival_ticket(uuid,uuid,text,uuid),public.mark_festival_stage_ready(uuid,integer,uuid),public.start_festival_performance(uuid,integer,uuid),public.record_festival_performance_delay(uuid,integer,integer,text,uuid),public.resolve_festival_performance(uuid,integer,uuid),public.cancel_runtime_festival_performance(uuid,integer,text,uuid),public.pause_festival_runtime(uuid,integer,uuid),public.resume_festival_runtime(uuid,integer,uuid),public.place_festival_emergency_hold(uuid,integer,boolean,text,uuid),public.clear_festival_emergency_hold(uuid,integer,uuid),public.close_festival_gates(uuid,integer,uuid),public.complete_festival_public_close(uuid,integer,uuid),public.complete_festival_site_clearance(uuid,integer,uuid),public.complete_festival_runtime(uuid,integer,uuid),public.recover_festival_runtime(uuid,integer,uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.process_due_festival_runtime_jobs(uuid,integer) TO service_role;
COMMENT ON FUNCTION public.resolve_festival_performance(uuid,integer,uuid) IS 'Exactly-once Festival adapter boundary over the versioned canonical gig engine; stores preliminary results and grants no rewards.';
COMMENT ON TABLE public.festival_runtime_snapshots IS 'Append-only recovery and later-settlement source; completed performance inputs/results and server seeds are never client writable.';
